"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { listConnections } from "@/lib/api";
import { isLoggedIn } from "@/lib/auth";
import AppHeader from "@/components/AppHeader";
import GradientOrbs from "@/components/GradientOrbs";
import TiltCard from "@/components/TiltCard";
import Magnetic from "@/components/Magnetic";

type Connection = {
  id: number;
  nickname: string;
  engine_type: string;
  host: string;
  database_name: string;
};

export default function HomePage() {
  const [connections, setConnections] = useState<Connection[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const router = useRouter();

  useEffect(() => {
    if (!isLoggedIn()) {
      router.push("/login");
      return;
    }
    listConnections()
      .then(setConnections)
      .finally(() => setLoading(false));
  }, [router]);

  const filteredConnections = connections.filter(
    (c) =>
      c.nickname.toLowerCase().includes(search.toLowerCase()) ||
      c.database_name.toLowerCase().includes(search.toLowerCase()) ||
      c.host.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <main className="relative min-h-screen bg-graphite overflow-x-hidden selection:bg-gold/30 selection:text-gold">
      <GradientOrbs />
      <AppHeader />

      <div className="relative z-10 mx-auto max-w-6xl px-6 py-12">
        {/* Header Hero Banner */}
        <div className="animate-fade-in-up mb-10 flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
          <div>
            <div className="mb-2 flex items-center gap-2">
              <span className="h-2 w-2 rounded-full bg-gold animate-pulse" />
              <span className="font-mono text-xs uppercase tracking-[0.25em] text-gold/90 font-semibold">
                Workspace Dashboard
              </span>
            </div>
            <h1 className="font-display text-4xl font-extrabold text-ink sm:text-5xl tracking-tight">
              Your Databases
            </h1>
            <p className="mt-2 text-sm text-mist max-w-lg">
              Manage your live PostgreSQL and MySQL connections or launch natural language SQL queries.
            </p>
          </div>

          <div className="flex items-center gap-3">
            <Magnetic strength={25}>
              <Link
                href="/connect"
                className="group relative inline-flex items-center gap-2.5 overflow-hidden rounded-2xl bg-gradient-to-r from-gold via-violet to-gold bg-[length:200%_auto] px-6 py-3.5 font-display text-sm font-bold text-graphite shadow-[0_15px_35px_-10px_rgba(242,184,75,0.4)] transition-all duration-300 hover:bg-[position:right_center] hover:shadow-[0_20px_45px_-8px_rgba(139,92,246,0.6)] active:scale-95"
              >
                <span className="text-base font-normal transition-transform duration-300 group-hover:rotate-90">＋</span>
                Connect Database
              </Link>
            </Magnetic>
          </div>
        </div>

        {/* Dashboard Stats & Search Bar */}
        <div className="mb-8 grid grid-cols-1 gap-4 sm:grid-cols-3">
          <div className="rounded-2xl border border-white/10 bg-surface/50 p-4 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase text-mist">Active Connections</p>
            <p className="mt-1 font-display text-2xl font-bold text-ink">
              {loading ? "..." : connections.length}
            </p>
          </div>

          <div className="rounded-2xl border border-white/10 bg-surface/50 p-4 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase text-mist">Security Engine</p>
            <p className="mt-1 font-display text-2xl font-bold text-gold flex items-center gap-2">
              <span className="h-2.5 w-2.5 rounded-full bg-gold" />
              sqlglot AST
            </p>
          </div>

          <div className="rounded-2xl border border-white/10 bg-surface/50 p-4 backdrop-blur-xl transition hover:border-white/20">
            <p className="font-mono text-xs uppercase text-mist">RAG Schema Retrieval</p>
            <p className="mt-1 font-display text-2xl font-bold text-violet">
              Top 5 Tables
            </p>
          </div>
        </div>

        {/* Search & Filter Bar */}
        {connections.length > 0 && (
          <div className="mb-6">
            <input
              type="text"
              placeholder="Search by nickname, host, or database name..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full rounded-2xl border border-white/10 bg-black/20 px-5 py-3 text-sm text-ink placeholder:text-mist/50 transition-all focus:border-gold/50 focus:outline-none focus:ring-4 focus:ring-gold/10"
            />
          </div>
        )}

        {/* Content Section */}
        {loading ? (
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="h-44 rounded-3xl border border-white/5 bg-surface/30 animate-pulse"
              />
            ))}
          </div>
        ) : filteredConnections.length === 0 ? (
          <div className="animate-fade-in-up flex flex-col items-center justify-center gap-5 rounded-3xl border border-dashed border-white/15 bg-surface/30 px-8 py-20 text-center backdrop-blur-2xl transition hover:border-gold/30">
            <div className="relative flex h-20 w-20 items-center justify-center rounded-3xl bg-gradient-to-br from-gold/20 via-violet/20 to-transparent p-0.5 shadow-2xl">
              <div className="flex h-full w-full items-center justify-center rounded-[22px] bg-graphite">
                <span className="font-display text-3xl text-gold">⛁</span>
              </div>
            </div>

            <div className="max-w-md">
              <h3 className="font-display text-2xl font-bold text-ink">No databases connected yet</h3>
              <p className="mt-2 text-sm text-mist leading-relaxed">
                Connect your Postgres or MySQL database to QueryMind. Raw passwords are Fernet-encrypted and all queries run safely through sqlglot.
              </p>
            </div>

            <Magnetic strength={20}>
              <Link
                href="/connect"
                className="mt-2 group relative inline-flex items-center gap-2 rounded-2xl border border-white/15 bg-white/5 px-6 py-3 font-display text-sm font-semibold text-ink backdrop-blur-xl transition-all duration-300 hover:border-gold/40 hover:bg-gold/10 hover:text-gold active:scale-95"
              >
                Connect Now
                <span className="transition-transform duration-300 group-hover:translate-x-1">→</span>
              </Link>
            </Magnetic>
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {filteredConnections.map((conn, i) => (
              <div
                key={conn.id}
                className="animate-fade-in-up"
                style={{ animationDelay: `${0.06 * i}s` }}
              >
                <TiltCard>
                  <Link
                    href={`/ask?connection_id=${conn.id}`}
                    className="group relative block h-full overflow-hidden rounded-3xl border border-white/10 bg-surface/60 p-6 backdrop-blur-xl transition-all duration-300 hover:-translate-y-1 hover:border-gold/40 hover:shadow-[0_20px_50px_-15px_rgba(0,0,0,0.7)]"
                  >
                    {/* Glowing Ambient Corner */}
                    <div className="absolute -right-12 -top-12 h-36 w-36 rounded-full bg-violet/15 blur-2xl transition-all duration-500 group-hover:bg-gold/25 group-hover:scale-125" />

                    <div className="relative flex items-start justify-between gap-2">
                      <div>
                        <span className="inline-block font-mono text-[11px] font-semibold uppercase tracking-wider text-gold">
                          ID: #{conn.id}
                        </span>
                        <h4 className="font-display text-xl font-bold text-ink transition-colors duration-200 group-hover:text-gold">
                          {conn.nickname}
                        </h4>
                      </div>

                      <span className="rounded-full border border-white/15 bg-white/5 px-3 py-1 font-mono text-[10px] font-semibold uppercase tracking-wider text-mist backdrop-blur-md">
                        {conn.engine_type}
                      </span>
                    </div>

                    <div className="relative mt-4 space-y-1 font-mono text-xs text-mist">
                      <p className="truncate flex items-center gap-1.5">
                        <span className="text-white/40">Host:</span> {conn.host}
                      </p>
                      <p className="truncate flex items-center gap-1.5">
                        <span className="text-white/40">DB:</span> {conn.database_name}
                      </p>
                    </div>

                    <div className="relative mt-6 flex items-center justify-between border-t border-white/10 pt-4 text-xs font-semibold text-gold">
                      <span className="flex items-center gap-1.5 text-mist group-hover:text-ink transition-colors">
                        <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
                        Ready to query
                      </span>
                      <span className="flex items-center gap-1 transition-transform duration-300 group-hover:translate-x-1">
                        Ask Question →
                      </span>
                    </div>
                  </Link>
                </TiltCard>
              </div>
            ))}
          </div>
        )}
      </div>
    </main>
  );
}
